-- ★中学校 10533件を学校マスタに投入する（2026-09-28 / 柴さんの指示）
--
-- 「同じ中学校出身の人がどんなところで活躍しているのか」を見られるようにするための器。
-- ⚠️★**促し（入力を勧める画面）はまだ作っていない。** 器だけ。
--    ⚠️ **マスタに入れても公開範囲は変わらない。** 学歴は以前から自由入力でも保存でき、
--       `/u/[id]` に出ていた。**「小学校を入れたら新しく公開される」ではない。**
--       ⚠️★ただし**促す**段になったら、生年月日と組み合わせると個人が特定されうるので、
--          **誰に見せるかを先に決めること**（未決）。
--
-- ── 出典 ────────────────────────────────────────────────────────────────────
-- 文部科学省「学校コード」**令和7年5月1日時点（確定版）**
--   https://www.mext.go.jp/b_menu/toukei/mext_01087.html
--   東日本 20251226-mxt_chousa01-000011635_2.csv / 西日本 ..._4.csv
--   ⚠️ **高校（`20260928190000`）と同じ2ファイル。** 種別ごとに migration を分けてある
--      ——検算の想定値が種別ごとに違うので、1本にすると失敗の切り分けができない。
--
-- 内訳: C1(中学校) 10,271 ＋ C2(義務教育学校) 262
--
-- ⚠️★**義務教育学校（C2 / 262校）を `junior_high` に入れている。** 小中一貫なので
--    小学校でもあるが、**`type` は1つしか持てず、`school_code` が UNIQUE なので2行に割れない。**
--    卒業段階で決めた ——**中等教育学校（D2）を `highschool` にしたのと同じ理屈。**
--    ⚠️ 結果として、義務教育学校は**小学校で探した人には出ない。**
--
-- ⚠️★★**校名にセル内改行が入っている行がある**（2026-09-28 に踏んだ）。
--    「幼保連携型認定こども園\nみどりのかぜ」の1件。**そのまま入れると画面で改行される。**
--    → 抽出時に `[\r\n\t]` を詰めてある。**全角空白は残す**（130件は元データの表記で、
--      推測で変えてよいものではない）。
--    ⚠️ 高校（`20260928190000`）には該当0件だったので影響なし。**次に別の種別を入れる人は
--       必ず洗うこと。** 気づいたのは値タプルの数が1件合わなかったからで、
--       **数えていなければそのまま入っていた。**
--
-- ── 何を入れないか ──────────────────────────────────────────────────────────
-- ⚠️★**`name_kana` は入れない。文科省データに読み仮名が無い**（推測値を投入しない）。
--    ⚠️ よみで引けるのは既存の大学だけ。**中学校はよみで検索できない。**
-- ⚠️ `logo_letter` / `logo_gradient` も入れない（3段階フォールバックで壊れない）。
-- ⚠️ 所在地・郵便番号も入れない。**都道府県だけ**。
-- ⚠️★**特別支援学校（E1 / 1,212校）・専修学校（H1 / 3,244）・各種学校（H2 / 1,138）は
--    入れていない。** `SCHOOL_TYPES` に対応する区分が無く、とくに特別支援学校は
--    **障害に関わる情報**なので、区分を作るかどうかの判断が別に要る。
--
-- ⚠️★**廃止校も入れる**（444件。学歴は過去の話なので）。
--    候補では `schoolOptionLabel()` が「廃止」と印を出す。**印を消さないこと。**
--
-- ⚠️ 都道府県は**都道府県番号（01〜47）**で引き、`src/lib/utils/location.ts` の
--    `PREFECTURES` と同じ表記に揃えてある（文科省は「青森」で県が付かない）。
--
-- ⚠️ 作業前ダンプ: .dumps/20260928-1649-ow_schools.sql（適用前 37行の時点）
-- ⚠️★**この migration の前に 5187 行ある想定。** 違えば中止する。

do $$
declare n bigint;
begin
  select count(*) into n from public.ow_schools;
  if n <> 5187 then
    raise exception '適用前の行数が想定（5187）と違う: %。順番が入れ替わっている。中止する', n;
  end if;
  select count(*) into n from public.ow_schools where type = 'junior_high';
  if n <> 0 then
    raise exception '中学校が既に % 件ある。二重投入になる。中止する', n;
  end if;
end $$;

