-- ⚠️ 検算。「INSERT が通った」だけでは足りない。
do $$
declare total bigint; mine bigint; cl bigint; dup bigint; n bigint;
begin
  select count(*) into total from public.ow_schools;
  if total <> 15720 then raise exception '全体が想定（15720）と違う: %', total; end if;

  select count(*) into mine from public.ow_schools where type='junior_high';
  if mine <> 10533 then raise exception '中学校が想定（10533）と違う: %', mine; end if;

  select count(*) into cl from public.ow_schools where type='junior_high' and closed_at is not null;
  if cl <> 444 then raise exception '中学校の廃止校が想定（444）と違う: %', cl; end if;

  select count(*) into dup from (
    select name from public.ow_schools where type='junior_high' group by name having count(*) > 1
  ) s;
  if dup <> 30 then raise exception '中学校の同名が想定（30組）と違う: %組', dup; end if;

  select count(*) into n from public.ow_schools
   where type='junior_high' and (prefecture is null or school_code is null);
  if n <> 0 then raise exception '中学校に都道府県か学校コードが空の行が % 件ある', n; end if;

  -- ★校名に改行・タブが入っていないこと（上の注記の検出器）
  select count(*) into n from public.ow_schools where type='junior_high' and name ~ '[\r\n\t]';
  if n <> 0 then raise exception '中学校の校名に改行かタブを含む行が % 件ある', n; end if;

  -- ★他の種別を動かしていないこと
  select count(*) into n from public.ow_schools where type='highschool';
  if n <> 5154 then raise exception '高校が想定（5154）と違う: %。他を動かした', n; end if;

  raise notice '中学校 % 件（うち廃止 % / 同名 %組）/ 全体 % 件', mine, cl, dup, total;
end $$;
